INSERT INTO `serie` (`id`, `nombre`, `fecha_lanzamiento`, `sinopsis`, `poster_src`, `fecha_creacion`, `valoracion`) VALUES
(1, 'Breaking Bad', 2008, 'Tras cumplir 50 años, Walter White (Bryan Cranston), un profesor de química de un instituto de Albuquerque, Nuevo México, se entera de que tiene un cáncer de pulmón incurable. Casado con Skyler (Anna Gunn) y con un hijo discapacitado (RJ Mitte), la brutal noticia lo impulsa a dar un drástico cambio a su vida: decide, con la ayuda de un antiguo alumno (Aaron Paul), fabricar anfetaminas y ponerlas a la venta. Lo que pretende es liberar a su familia de problemas económicos cuando se produzca el fatal desenlace.', 'img/posters/BB_POSTER.jpg', '2024-03-01', NULL),
(2, 'Better Call Saul', 2015, 'Precuela de la serie \"Breaking Bad\", centrada en el personaje del abogado Saul Goodman (Bob Odenkirk), seis años antes de conocer a Walter White. La serie cuenta cómo un picapleitos de poca monta llamado Jimmy McGill, con problemas para llegar a fin de mes, se convierte en el abogado criminalista Saul Goodman.', 'img/posters/BCS_POSTER.jpg', '2024-03-01', NULL),
(3, 'Juego de Tronos', 2011, 'En una tierra donde los veranos duran décadas y los inviernos pueden durar toda una vida, los problemas acechan. Desde las maquinaciones del sur a las salvajes tierras del este, pasando por el helado norte y el milenario muro que protege el reino de las fuerzas tenebrosas, dos poderosas familias mantienen un enfrentamiento letal por gobernar los Siete Reinos de Poniente. Mientras la traición, la lujuria y las fuerzas sobrenaturales sacuden los pilares de los reinos, la sangrienta batalla por el trono de Hierro tendrá consecuencias imprevistas y trascendentales. El invierno se acerca. Que empiece \'Juego de tronos\'.', 'img/posters/GOT_POSTER.jpg', '2024-03-07', NULL),
(4, 'Black Mirror', 2011, 'Black Mirror es una serie de televisión británica creada por Charlie Brooker que muestra el lado oscuro de la vida y la tecnología. La serie es producida por Zeppotron para Endemol. En cuanto al contenido del programa y la estructura, Brooker ha señalado que \"cada episodio tiene un tono diferente, un entorno diferente, incluso una realidad diferente, pero todos son acerca de la forma en que vivimos ahora - y la forma en que podríamos estar viviendo en 10 minutos si somos torpes\".', 'img/posters/BLACKMIRROR_POSTER.jpg', '2024-03-07', NULL),
(5, 'BoJack Horseman', 2014, 'En un mundo donde humanos y animales antropomórficos conviven, el protagonista de la serie es el caballo BoJack Horseman (Will Arnett), protagonista de la telecomedia \"Horsin\' Around\" en la década de los 90. Después de años de decadencia y una tormentosa vida personal, BoJack se propone volver al candelero a través de una autobiografía para la que contará con ayuda de una escritora fantasma, Diane Nguyen (Alison Brie). Pero BoJack también tendrá que lidiar con las exigencias de su exnovia y agente, la gata Princess Carolyn, su compañero de piso, Todd Chávez, y su amienemigo Mr. Peanutbutter, un perro labrador que es novio de Diane y triunfó con una sitcom muy similar a \"Horsin\' Around\".', 'img/posters/BOJACK_POSTER.jpg', '2024-03-07', NULL),
(6, 'Shōgun', 2024, 'Ambientada en el Japón del siglo XVII, Shōgun sigue el choque de dos hombres ambiciosos de diferentes mundos y una misteriosa samurái femenina: John Blackthorne, un intrépido marinero inglés que naufraga en Japón, una tierra cuya cultura desconocida finalmente lo redefine; Lord Toranaga, un astuto y poderoso daimyo en conflicto con sus peligrosos rivales políticos; y Lady Mariko, una mujer con habilidades invaluables pero lazos familiares deshonrosos, que debe demostrar su valor y lealtad', 'img/posters/SHOGUN_POSTER.jpg', '2024-03-08', NULL),
(7, 'La Casa del Dragón', 2022, 'Basada en la novela de George R. R. Martin Fuego y sangre, la historia de La casa del dragón tiene lugar 200 años antes de los eventos de Juego de tronos y 172 antes del nacimiento de Daenerys Targaryen. Cuenta la historia del origen del final de la Casa Targaryen,​ y el desarrollo de un conflicto intrafamiliar conocido como la Danza de los Dragones, que deriva de la división de la realeza en dos bandos por la elección del heredero al trono de hierro.', 'img/posters/HOTD_POSTER.jpg', '2024-03-08', NULL),
(8, 'Chernobyl', 2019, 'En Abril de 1986, la Central Nuclear de Chernóbil en Ucrania (en aquel entonces, la Unión Soviética), sufrió una explosión masiva que liberó material radioactivo en Bielorrusia, Rusia, Ucrania, así como en zonas de Escandinavia y Europa Central. La serie relata lo que aconteció en 1986, en uno de los mayores desastres provocados por el hombre en la historia reciente, así como los sacrificios realizados para salvar al continente de un desastre sin precedentes.', 'img/posters/CHERNOBYL_POSTER.jpg', '2024-03-08', NULL),
(9, 'Los Soprano', 1999, 'Los Soprano (The Sopranos) es una serie de televisión estadounidense creada y producida por David Chase. La serie se estrenó en Estados Unidos el 10 de enero de 1999 por el canal de televisión por cable HBO, que la emitió ininterrumpidamente hasta su desenlace, el 10 de junio de 2007. La trama de la serie gira en torno al mafioso de Nueva Jersey Tony Soprano (James Gandolfini) y las dificultades que enfrenta tanto en su hogar como en la organización criminal que dirige. A su vez, la serie también se centra en la historia de los personajes cercanos a Tony, especialmente su esposa Carmela (Edie Falco) y su sobrino y protegido Christopher Moltisanti (Michael Imperioli).', 'img/posters/SOPRANO_POSTER.jpg', '2024-03-08', NULL),
(10, 'Bajo Escucha', 2002, 'David Simon, creador y co-guionista de la mini- serie de HBO tres veces ganadora del premio Emmy The Corner, este sencillo y extremadamente realista drama sigue una caótica y controvertida investigación de drogas y asesinatos en Baltimore que conllevará peligrosos pinchazos telefónicos y continua vigilancia. Mostrando ambas perspectivas, de la policía y de sus criminales, la serie captura un universo donde distinguir entre el bien y el mal, el delito y la condena, es siempre desafío.', 'img/posters/THEWIRE_POSTER.jpg', '2024-03-08', NULL),
(11, 'Peaky Blinders', 2013, 'Una familia de pandilleros asentada en Birmingham, Reino Unido, tras la Primera Guerra Mundial (1914-1918), dirige un local de apuestas hípicas. Las actividades del ambicioso jefe de la banda llaman la atención del Inspector jefe Chester Campbell, un detective de la Real Policía Irlandesa que es enviado desde Belfast para limpiar la ciudad y acabar con la banda.', 'img/posters/PEAKY_POSTER.jpg', '2024-03-08', NULL),
(12, 'Dark', 2017, 'En la ciudad de Winden comienzan a desaparecer niños,​ sacando a la luz las relaciones fracturadas, vidas dobles y el pasado oscuro de cuatro familias (Kahnwald, Nielsen, Tiedemann y Doppler) que viven allí, y revelando un misterio que abarca cuatro generaciones.', 'img/posters/DARK_POSTER.jpg', '2024-03-08', NULL),
(13, 'Ted Lasso', 2020, 'El programa sigue a Ted Lasso, un entrenador de fútbol americano universitario que es contratado para entrenar a un equipo de fútbol inglés cuya dueña secretamente espera que su inexperiencia lo lleve al fracaso, pero cuyo liderazgo campechano y optimista resulta inesperadamente exitoso.', 'img/posters/LASSO_POSTER.jpg', '2024-03-08', NULL),
(15, 'Succession', 2018, 'Succession cuenta las tribulaciones de la familia Roy —Logan Roy y sus cuatro hijos— que controlan uno de los mayores conglomerados de medios audiovisuales y entretenimiento del mundo. La serie rastrea sus vidas mientras contemplan lo que les deparará el futuro una vez que el patriarca de la familia abandone la compañía.', 'img/posters/SUCCESSION_POSTER.jpg', '2024-03-08', NULL),
(16, 'Perdidos', 2004, 'Lost trata sobre un grupo de supervivientes de un accidente aéreo producido en una aparente isla desierta del pacífico. Unas 20 o 30 personas esperan a que vayan a rescatarlas. Éstas tendrán que luchar por su supervivencia, día a día. Será entonces cuando descubran que la isla está llena de misterios ocultos.', 'img/posters/LOST_POSTER.jpg', '2024-03-08', NULL),
(17, 'The Last Dance', 2020, 'Docuserie repleta de material inédito de la temporada 1997-98 , que muestra la carrera del legendario baloncestista Michael Jordan, uno de los mayores iconos del deporte de todos los tiempos, y su trayectoria con los Chicago Bulls en los años 90.', 'img/posters/TLDANCE_POSTER.jpg', '2024-03-08', NULL),
(18, 'The Walking Dead', 2010, '\"The Walking Dead\" está ambientada en un futuro apocalíptico con la Tierra devastada por el efecto de un cataclismo, que ha provocado la mutación en zombies de la mayor parte de los habitantes del planeta. La serie, explora las dificultades de los protagonistas para sobrevivir en un mundo poblado por el horror, así como las relaciones personales que se establecen entre ellos, en ocasiones también una amenaza para su supervivencia.', 'img/posters/TWD_POSTER.jpg', '2024-03-08', NULL),
(20, 'El Simpatizante', 2024, 'Un thriller de espionaje y una sátira intercultural sobre las luchas de un espía comunista mitad francés, mitad vietnamita durante los últimos días de la Guerra de Vietnam y su exilio resultante en los Estados Unidos.', 'img/posters/SYMPATHIZER_POSTER.jpg', '2024-06-07', NULL),
(21, '1899', 2022, 'Al cruzar el océano del viejo al nuevo continente, varios inmigrantes de diversas nacionalidades viven una pesadilla a bordo de un segundo barco a la deriva.', 'img/posters/1899_POSTER.jpg', '2024-06-07', NULL),
(22, 'Fargo', 2014, 'Un vendedor ve cómo su mundo cambia por completo con la llegada de un misterioso y salvaje desconocido. Serie basada en la película del mismo título de los hermanos Coen, que sin embargo presenta personajes diferentes y se ambienta en 2006.', 'img/posters/FARGO_POSTER.jpg', '2024-06-07', NULL),
(23, 'Friends', 1994, 'Las aventuras de seis jóvenes neoyorquinos unidos por una divertida amistad. Entre el amor, el trabajo y la familia, comparten sus alegrías y preocupaciones en el Central Perk, su café favorito.', 'img/posters/FRIENDS_POSTER.jpg', '2024-06-07', NULL),
(24, 'Mindhunter', 2017, 'Un agente del FBI, experto en asesinos en serie, inventa técnicas de creación de perfiles mientras persigue a violadores y asesinos famosos.', 'img/posters/MINDHUNTER_POSTER.jpg', '2024-06-07', NULL),
(25, 'The Mandalorian', 2019, 'En el anárquico período tras el hundimiento del Imperio Galáctico, un cazarrecompensas con armadura conocido solo como El Mandaloriano emprende una misión bien remunerada aunque enigmática.', 'img/posters/MANDALORIAN_POSTER.jpg', '2024-06-07', NULL),
(26, 'Narcos', 2015, 'La verdadera historia de los poderosos y violentos cárteles colombianos sirve de hilo conductor en esta serie dramática de mafiosos de gran realismo.', 'img/posters/NARCOS_POSTER.jpg', '2024-06-07', NULL),
(27, 'Rick y Morty', 2013, 'Comedia animada que narra las aventuras de un científico loco Rick Sánchez, que regresa después de 20 años para vivir con su hija, su marido y sus hijos Morty y Summer.', 'img/posters/R&M_POSTER.jpg', '2024-06-07', NULL),
(28, 'Roma', 2015, 'Cuatro siglos después de la fundación de la República (509 a.C.), Roma es la ciudad más poderosa del mundo, una metrópoli cosmopolita de un millón de personas, el epicentro de un imperio en expansión. La República se basó en la separación de poderes y creó los mecanismos necesarios para evitar que un solo hombre acumulara demasiado poder. Sin embargo, con el paso del tiempo, la corrupción, el lujo y los excesos fueron carcomiendo esos principios.', 'img/posters/ROME_POSTER.jpg', '2024-06-07', NULL),
(29, 'Stranger Things', 2016, 'A raíz de la desaparición de un niño, un pueblo desvela un misterio relacionado con experimentos secretos, fuerzas sobrenaturales aterradoras y una niña muy extraña.', 'img/posters/STRANGERTHINGS_POSTER.jpg', '2024-06-07', NULL),
(30, 'The Bear', 2022, 'Un joven chef lucha por transformar una tienda de bocadillos junto a un equipo de cocineros novatos.', 'img/posters/THEBEAR_POSTER.jpg', '2024-06-07', NULL),
(31, 'The Boys', 2019, 'La serie tiene lugar en un mundo en el que los superhéroes representan el lado oscuro de la celebridad y la fama. Un grupo de vigilantes que se hacen llamar \"The Boys\" decide hacer todo lo posible por frenar a los superhéroes que están perjudicando a la sociedad, independientemente de los riesgos que ello conlleva.', 'img/posters/THEBOYS_POSTER.jpg', '2024-06-07', NULL),
(32, 'The Office (US)', 2015, 'Steve Carell protagoniza The Office, un fresco y divertido vistazo, con formato pseudo-documental, al día a día en la vida de unos excéntricos trabajadores de la empresa Dunder Mifflin. El serio pero despistadísimo director Michael Scott se considera un magnífico jefe y mentor, pero realmente inspira más críticas que respeto a sus empleados.', 'img/posters/THEOFFICEUS_POSTER.jpg', '2024-06-07', NULL),
(33, 'The Last of Us', 2023, 'Año 2023, veinte años después del comienzo de una plaga mundial que infectó a población con un hongo mutado transformando a las personas en unas criaturas caníbales, el contrabandista Joel tiene la misión de escoltar a la adolescente Ellie por un mundo postapocalíptico en el nada va a ser fácil para los viajeros. Joel todavía vive atormentado por el recuerdo de su única hija. Ellie es portadora de algo que podría cambiar el destino de la humanidad ¿Conseguirán sobrevivir los dos?', 'img/posters/TLOU_POSTER.jpg', '2024-06-07', NULL),
(34, 'Vikingos', 2013, 'Sigue las aventuras de Ragnar Lothbrok, el héroe más grande de su época. La serie narra las sagas de la banda de hermanos vikingos de Ragnar y su familia, cuando él se levanta para convertirse en el rey de las tribus vikingas. Además de ser un guerrero valiente, Ragnar encarna las tradiciones nórdicas de la devoción a los dioses, la leyenda dice que él era un descendiente directo de Odín, el dios de la guerra y los guerreros.', 'img/posters/VIKINGS_POSTER.jpg', '2024-06-07', NULL),
(35, 'The Crown', 2016, 'Drama sobre las rivalidades políticas y los romances acaecidos durante el reinado de Isabel II, así como de los eventos que moldearían la segunda mitad del siglo XX.', 'img/posters/THECROWN_POSTER.jpg', '2024-06-07', NULL),
(36, 'Tokyo Vice', 2022, 'Un relato de primera mano del golpe a la Policía Metropolitana de Tokio siguiendo a Jake Adelstein, un periodista estadounidense que se integra en el escuadrón policial de Tokio Vice para revelar la corrupción.', 'img/posters/TOKYOVICE_POSTER.jpg', '2024-06-07', NULL),
(37, 'Devs', 2020, 'Lily Chan, una joven ingeniera de software que, tras el aparente suicido de su novio, comienza a investigar al CEO de la empresa para la que trabaja, Forest. En su búsqueda, descubre una conspiración tecnológica que podría cambiar el mundo.', 'img/posters/DEVS_POSTER.jpg', '2024-06-07', NULL),
(38, 'The Acolyte', 2024, '\"The Acolyte\" lleva a los espectadores a una galaxia de oscuros secretos y poderes emergentes del lado oscuro en los últimos días de la era de la Alta República.', 'img/posters/ACOLYTE_POSTER.jpg', '2024-06-07', NULL),
(39, 'The Umbrella Academy', 2019, 'Un grupo disuelto de superhéroes se reúne después de que su padre adoptivo, quien los entrenó para salvar el mundo, muere.', 'img/posters/UMBRELLA_POSTER.jpg', '2024-06-07', NULL),
(40, 'Futurama', 1999, 'Ambientada en la ciudad de \"Nueva Nueva York\" en el año 3000, la serie comienza con Philip J. Fry, un joven repartidor de pizza neoyorquino fracasado y desmotivado que es criogénicamente congelado por accidente la Nochevieja de 1999. Mil años después es descongelado, encontrándose en Nueva Nueva York el 31 de diciembre de 2999. El intento de Fry por escapar de la entonces obligatoria asignación laboral como repartidor termina cuando es contratado en Planet Express, una pequeña compañía de mensajería intergaláctica propiedad de su sobrino lejano, como repartidor. La serie trata sobre las aventuras de Fry y sus colegas cuando viajan por el universo haciendo repartos para Planet Express.', 'img/posters/FUTURAMA_POSTER.jpg', '2024-06-07', NULL),
(41, 'Arcane', 2021, 'Con las dispares ciudades de Piltover y Zaun como telón de fondo, dos hermanas luchan en bandos opuestos de una guerra entre tecnologías mágicas y creencias enfrentadas.', 'img/posters/ARCANE_POSTER.jpg', '2024-06-07', NULL),
(42, 'Fullmetal Alchemist: Brotherhood', 2009, 'La historia se centra en los hermanos Edward y Alphonse Elric, quienes viven en un pequeño pueblo de un país ficticio llamado Amestris. Su padre, Hohenheim, se había marchado de su casa cuando aún eran pequeños y años más tarde su madre, Trisha Elric, muere por una enfermedad terminal, dejando a los hermanos Elric solos. Después de la muerte de su madre, Edward decide resucitarla a través de la alquimia, una de las técnicas científicas más avanzadas conocidas por el hombre. Sin embargo, el intento resulta fallido y como consecuencia Edward pierde su pierna izquierda, y Alphonse su cuerpo. En un esfuerzo por salvar a su hermano, Edward sacrifica su brazo derecho para sellar el alma de Alphonse en una armadura. Tras esto, un alquimista llamado Roy Mustang visita a los hermanos Elric y le propone a Edward convertirse en un miembro de las Fuerzas Armadas del Estado y así encontrar una forma de recuperar sus cuerpos.', 'img/posters/FMA_POSTER.jpg', '2024-06-07', NULL),
(43, 'Slam Dunk', 1993, 'Slam Dunk trata sobre la vida de Hanamichi Sakuragi, un pandillero que se convierte en un gran jugador de baloncesto, sólo para tratar de ligar con una chica de su escuela.', 'img/posters/SLAMDUNK_POSTER.jpg', '2024-06-07', NULL),
(44, 'Merlí', 2015, 'Merlí es un profesor de una materia denostada y apreciada a partes iguales, filosofía. Un tipo contradictorio, y con virtudes y defectos a la par. La producción se centra en la relación del maestro con sus alumnos y, sobre todo, en los conflictos entre padres e hijos, estudiantes y profesores.', 'img/posters/MERLI_POSTER.jpg', '2024-06-07', NULL),
(45, 'Neon Genesis Evangelion', 1995, 'En el año 1999, en la Antártida, ocurrió un cataclismo llamado \"El Segundo Impacto\", como resultado de un incidente ocasionado por unos seres conocidos como \"Ángeles\". Gran parte de la Tierra quedó devastada por el fenómeno, y la mitad de la población sucumbió en la catástrofe, aunque ahora la humanidad gradualmente se va recuperando. Años después, en el 2015, los \"Ángeles\" regresan y comienzan a atacar a la Tierra... Cada uno de los \"Ángeles\" es diferente de los demás, excepto por el hecho de que todos pueden generar un impenetrable escudo protector llamado Campo AT. La organización NERV revela su nuevo proyecto con miras a salvar el mundo: gigantes y bio-mecánicos robots conocidos como Evas, que son unos de las pocas fuerzas sobre la Tierra capaces de enfrentar a los \"Ángeles\". Sólo niños específicos pueden pilotar los Evas: Shinji Ikari, el hijo de el jefe de NERV y que no desea pelear, la reservada Rei Ayanami y la exaltada (y algo amante del combate) Asuka Langley. Mientras combaten a los \"Ángeles\" uno a uno, van descubriendo más y más acerca de la naturaleza y el futuro de la humanidad...', 'img/posters/NGE_POSTER.jpg', '2024-06-07', NULL),
(46, 'InuYasha', 2000, 'InuYasha es el nombre de un demonio que en su día sellaron para que no provocara más problemas. Pero Kagome, fruto del destino, consigue atravesar la barrera mágica que separa el mundo actual con el de las guerras civiles, y quita el sello a Inu Yasha debido a la amenaza de cierto monstruo. Kagome posee la joya de las cuatro almas, que permite ganar gran poder, y ella será fruto del recelo de muchos monstruos en busca de ella. Pero la joya se ha roto en mil y un pedazos, e Inu Yasha y Kagome partirán en busca de todos los trozos de la joya.', 'img/posters/INUYASHA_POSTER.jpg', '2024-06-07', NULL),
(47, 'Planeta Tierra', 2006, '\'Planeta Tierra\' es una serie de televisión estrenada en 2006 y producida por la Sección de Historia Natural de la BBC. Ganadora de un premio Emmy, esta serie tardó alrededor de cinco años en ser realizada por completo. Fue, además, el documental de naturaleza más caro jamás producido por la BBC, y fue descrito por sus creadores como \"la mirada definitiva a la diversidad de nuestro planeta\".', 'img/posters/PLANETATIERRA_POSTER.jpg', '2024-06-07', NULL),
(48, 'Hermanos de Sangre', 2001, 'Miniserie de TV de 10 episodios que se basa en el bestseller de Stephen E. Ambrose \"Band Of Brothers\". Narra la historia de la Easy Company, un batallón americano del regimiento 506 de paracaidistas que luchó en Europa durante la II Guerra Mundial (1939-1945). Incluye entrevistas a los supervivientes, recuerdos de los periodistas y cartas de los soldados.', 'img/posters/BANDOFBROTHERS_POSTER.jpg', '2024-06-07', NULL),
(49, 'Cowboy Bebop', 1998, 'La tripulación de la nave Bebop solo intenta ganar dinero, y son la pandilla de caza-recompensas más divertida del año 2071.', 'img/posters/SPACECOWBOY_POSTER.jpg', '2024-06-07', NULL),
(50, 'Sherlock', 2010, 'Ubicada en el Londres del siglo XXI, la serie sigue los pasos del excéntrico detective Sherlock Holmes junto a su compañero el doctor John H. Watson, en su búsqueda por resolver los brutales crímenes que se van desarrollando.', 'img/posters/SHERLOCK_POSTER.jpg', '2024-06-07', NULL),
(51, 'Gambito de Dama', 2020, 'Kentucky, años 50. En el orfanato, una chica descubre que posee un talento extraordinario para el ajedrez mientras intenta superar una adicción.', 'img/posters/QUEENSGAMBIT_POSTER.jpg', '2024-06-07', NULL),
(52, 'Miércoles', 2022, 'Miércoles Addams, lista, sarcástica y un poco muerta por dentro, investiga una oleada de asesinatos mientras hace amigos —y enemigos— en la Academia Nunca Más.', 'img/posters/WEDN_POSTER.jpg', '2024-06-07', NULL),
(53, 'Lucifer', 2016, 'La serie se centrará en Lucifer (Tom Ellis) quien, aburrido e infeliz como el Señor del Infierno, dimite de su trono y abandona su reino para trasladarse a la ciudad de Los Angeles y abrir un lujoso piano-bar llamado Lux. Una vez allí ayudará a la policía a castigar a los más peligrosos criminales de la ciudad.', 'img/posters/LUCIFER_POSTER.jpg', '2024-06-07', NULL),
(54, 'Berserk', 1997, 'Durante más de 100 años, los magníficos ejércitos de Chuder y los de la región central han luchado en sangrientas batallas. Tan sólo la impenetrable fortaleza Doldery mantiene al Imperio de Chuder a salvo de todas las guerras que les rodean. La banda de los Halcones han tomado posiciones en la gran ofensiva. En esta batalla, las tropas de la región central podrán llegar hasta las puertas de la legendaria fortaleza de Chuder y desafiar al ejército invencible del General Boscongn.', 'img/posters/BERSERK_POSTER.jpg', '2024-06-07', NULL),
(55, 'Riverdale', 2017, 'Archie y sus amigos de Riverdale se verán envueltos en un siniestro misterio al tiempo que lidian con las complicaciones del sexo, el amor, los estudios y la familia.', 'img/posters/RIVERDALE_POSTER.jpg', '2024-06-07', NULL),
(56, 'Hijos de la Anarquia', 2008, 'Serie ambientada en la localidad ficticia de Charming, situada en el Norte de California. Su protagonista es Jackson “Jax” Teller(Chalie Hunnam – “Hijos de los hombres”, “Cold Mountain”), un treintañero que, como el resto de su familia, pertenece a la banda de moteros Sons of Anarchy Motorcycle Club Redwood Original (SAMCRO en su acrónimo), un clan formado por antiguos veteranos de la guerra de Vietnam que se dedican a trapichear con todo, especialmente con armas que venden a bandas rivales.', 'img/posters/SOA_POSTER.jpg', '2024-06-07', NULL),
(57, 'La Granja de Clarkson', 2021, 'Un año intenso, arduo y muy divertido en la vida del agricultor más insólito de Gran Bretaña, Jeremy Clarkson. Únete a Jeremy y a su grupo de socios agrícolas mientras se enfrentan a un tiempo de locos, animales desobedientes, cultivos que no crecen y una pandemia inesperada. Verás a Jeremy Clarkson como nunca antes lo habías visto.', 'img/posters/CLARKSON_POSTER.jpg', '2024-06-07', NULL),
(58, 'Cortar por la Línea de Puntos', 2021, 'Durante un viaje con amigos, un dibujante y su conciencia (representada por un armadillo) reflexionan sobre la vida y el amor no correspondido.', 'img/posters/CPLLDP_POSTER.jpg', '2024-06-07', NULL),
(59, 'Separación', 2022, 'Mark dirige un equipo de oficinistas cuyos recuerdos se han separado quirúrgicamente entre los de su trabajo y los de su vida personal. Cuando un misterioso colega aparece fuera del trabajo, empieza un viaje para descubrir la verdad sobre sus empleos.', 'img/posters/SEPARACION_POSTER.jpg', '2024-06-07', NULL),
(60, 'Outer Banks', 2020, 'En una isla de ricos y pobres, un grupo de adolescentes formado por John B, JJ, Pope y Kiara, encuentran un misterioso barco hundido tras un huracán, y se adentran en una peligrosa aventura para buscar un legendario tesoro vinculado a la desaparición del padre de John B.', 'img/posters/OUTERBANKS_POSTER.jpg', '2024-06-07', NULL),
(61, 'Fallout', 2024, 'Basado en una de las sagas de videojuegos más importantes de todos los tiempos, Fallout es la historia de los que tienen y de los que no tienen en un mundo en el que prácticamente no queda nada para tener. 200 años después del apocalipsis, los apacibles habitantes de los refugios de lujo se ven obligados a regresar al infierno irradiado que dejaron sus antepasados - y se sorprenden al descubrir que les espera un universo increíblemente complejo, alegremente extraño y muy violento. De los productores ejecutivos Jonathan Nolan y Lisa Joy, los creadores de Westworld, protagonizada por Ella Purnell, Aaron Moten, Walton Goggins y más.', 'img/posters/FALLOUT_POSTER.jpg', '2024-06-07', NULL),
(62, 'Solo Asesinatos en el Edificio', 2021, 'Tres extraños que comparten la obsesión por los crímenes reales y de repente se ven envueltos en uno al investigar la misteriosa muerte de un vecino en su edificio de Nueva York.', 'img/posters/SAED_POSTER.jpg', '2024-06-07', NULL),
(63, 'Ben 10', 2005, 'Ben 10 cuenta las aventuras de Ben Tennyson, un niño normal de diez años que descubre en sus vacaciones de verano un extraño reloj extraterrestre dentro de un meteorito que chocó contra la Tierra. Ben pronto se da cuenta de que este reloj no es un aparato cualquiera, sino el artefacto alienígena mas poderoso del Universo, el Omnitrix. Este reloj le permite transformarse en diez seres extraterrestres distintos sin perder su personalidad, aunque eventualmente sería capaz de desbloquear nuevos alienígenas. Ahora, con la ayuda del Omnitrix, Ben, junto a su prima Gwen y a su abuelo Max combatirán un sinfín de villanos, asegurando que este verano sea sin duda \"el mejor verano de la historia\". En 2008 se estrenó una segunda serie que continúa la historia de esta primera, \"Ben 10: Alien Force\".', 'img/posters/BEN10_POSTER.jpg', '2024-06-07', NULL),
(64, 'The Gentlemen', 2024, 'Eddie Horniman es un hombre que hereda inesperadamente la enorme finca rústica de su padre y descubre que forma parte de un imperio del cannabis. Por si fuera poco, varios hampones de Gran Bretaña reclaman un trozo del pastel. Decidido a mantener a su familia lejos de las garras de los mafiosos, Eddie intenta vencerlos en su propio territorio, pero a medida que se sumerge en el mundo criminal, empieza a encontrarle el gusto.', 'img/posters/THEGENTLEMEN_POSTER.jpg', '2024-06-07', NULL),
(65, 'RIPLEY', 2024, 'Adaptación de la serie de novelas de Patricia Highsmith sobre Tom Ripley. Años 60. Un millonario contrata al estafador Tom Ripley para que viaje a Italia e inste a su hedonista hijo a regresar a casa. La aceptación del trabajo por parte de Tom hace que éste se vea rodeado de riqueza, lujos y privilegios, haciéndose pasar por quien no es. Pero para conservar la vida que tanto desea, Tom tendrá que tejer una red de mentiras.', 'img/posters/RIPLEY_POSTER.jpg', '2024-06-07', NULL),
(66, 'Monster', 2004, 'El doctor Kenzo Tenma es un prometedor neurocirujano japonés que ejerce en el Eisler Memorial Hospital de Dusseldorf. Lo tiene todo en la vida; un trabajo que le apasiona y en el que demuestra una habilidad increíble, y una novia rica y guapa. Sin embargo, un día decide ignorar una orden de su superior y salva a un niño desconocido en lugar de la vida del alcalde de la ciudad. Como consecuencia de esto pierde su privilegiado trabajo y a su novia. Poco después, los médicos que lo destituyeron aparecen muertos y él se convierte en principal sospechoso. Tenna está dispuesto a llegar hasta el fondo de éstas y otras muertes e investigar la verdad sobre el monstruo que hay detrás de todo el asunto.', 'img/posters/MONSTER_POSTER.jpg', '2024-06-07', NULL),
(67, 'Mi Reno de Peluche', 2024, 'Cuando un cómico en apuros tiene un gesto amable con una mujer vulnerable, desencadena una obsesión enfermiza que amenaza con destrozar la vida de ambos.', 'img/posters/RENO_POSTER.jpg', '2024-06-07', NULL),
(68, 'Slow Horses', 2022, 'Después de una misión de entrenamiento fallida y públicamente vergonzosa, el agente británico del MI5, River Cartwright, es exiliado a Slough House, un purgatorio administrativo para los marginados del servicio.', 'img/posters/SLOWHORSES_POSTER.jpg', '2024-06-07', NULL),
(69, 'Pachinko', 2022, 'Narra la historia épica e íntima que comienza con un amor prohibido y va creciendo hasta convertirse en una saga que viaja entre Corea, Japón y Estados Unidos para contar un relato de guerra y paz, amor y pérdida, triunfo y ajuste de cuentas.', 'img/posters/PACHINKO_POSTER.jpg', '2024-06-07', NULL),
(70, 'Cómo Conocí a Vuestra Madre', 2005, 'Ted (Josh Radnor) les cuenta a sus dos hijos cómo conoció a su madre y cómo fue su vida hasta que, por fin, encontró el amor verdadero. Contó para ello con la ayuda de su amigo Barney (Neil Patrick Harris), un joven algo extravagante, adicto a los somníferos y muy hábil para conocer mujeres. Cuando Ted conoce a Robin (Cobie Smulders), una impresionante joven canadiense que acaba de mudarse a Nueva York, está completamente seguro de que es amor a primera vista.', 'img/posters/HIMYM_POSTER.jpg', '2024-06-07', NULL),
(71, 'El Príncipe de Bel-Air', 1990, 'Will Smith interpreta a un joven de Philadelphia que se traslada a vivir con sus ricos parientes al lujoso barrio de Bel-Air, en California. La familia la forman sus tíos y sus primos Carlton, Hilary y Ashley; además está el mayordomo Geoffrey. El incorregible y avispado Will deberá adaptarse a su nueva familia, a un nivel de vida al que no estaba acostumbrado y a las reglas de convivencia impuestas por su tío Phil, un juez muy preocupado por su reputación.', 'img/posters/BELAIR_POSTER.jpg', '2024-06-07', NULL),
(72, 'Aquí No Hay Quien Viva', 2003, 'Exitosa telecomedia que narra la vida de una peculiar comunidad de vecinos de la calle \"Desengaño 21\": tres plantas, dos pisos por planta, una portería y un local contiguo albergan a los variopintos vecinos de esta sitcom cuyo plato fuerte eran sus ágiles guiones y sus distinguibles personajes: el presidente de la comunidad, su ambiciosa mujer, las vecinas cotillas, los vecinos gays, el sufrido portero, etc.', 'img/posters/ANHQV_POSTER.jpg', '2024-06-07', NULL),
(73, 'Prison Break', 2005, 'Michael Scofield (Wentworth Miller) es un hombre desesperado en un situación desesperada. Su hermano Lincoln Burrows (Dominic Purcell), condenado a la pena capital está a la espera de ser ejecutado. A pesar de todas las evidencias, Michael cree en su inocencia, por lo que decide robar un banco para dejarse atrapar y ser encarcelado en la misma prisión que su hermano. Su objetivo: escapar juntos.', 'img/posters/PRISONBREAK_POSTER.jpg', '2024-06-07', NULL),
(74, 'True Detective', 2014, 'Dos detectives de Lousiana, Rust Cohle (Matthew McConaughey) y Martin Hart (Woody Harrelson), vuelven a investigar el difícil caso de un asesino en serie en el que ya habían trabajado. Obligados a regresar a un mundo tan siniestro, el avance de la investigación y el mayor conocimiento mutuo les enseñan que la oscuridad reside a ambos lados de la ley.', 'img/posters/TRUEDETECTIVE_POSTER.jpg', '2024-06-07', NULL),
(75, 'Sexo en Nueva York', 1998, 'Narra las aventuras amorosas y sexuales de cuatro neoyorquinas solteras e independientes: la columnista Carrie Bradshaw (Parker) y sus tres mejores amigas, la abogada Miranda (Cynthia Nixon), la pija Charlotte York (Kristin Davis) y la promiscua Samantha Jones (Kim Cattrall). El programa se hizo famoso por rodar escenas en las calles, los bares, restaurantes y discotecas de Nueva York.', 'img/posters/SENY_POSTER.jpg', '2024-06-07', NULL),
(76, 'Oliver y Benji', 1983, 'Basado en el popular manga homónimo creado por Yoichi Takahashi en 1981. La historia comienza cuando Tsubasa Ozora (Oliver), de 12 años de edad, se muda a Shizuoka. El chaval tiene la ilusión de jugar con el equipo más famoso de esa ciudad: el Shutetsu, en el cual milita el mejor portero de la liga nacional: Genzo Wakabayashi (Benji). Sin embargo, el protagonista tendrá que entrenar duro y jugar agotadores partidos -incluso lesionado- para alcanzar su sueño: ganar el campeonato nacional de fútbol.', 'img/posters/OLIVER&BENJI_POSTER.jpg', '2024-06-07', NULL),
(77, 'Twin Peaks', 1990, 'El excéntrico agente del FBI Dale Cooper (Kyle MacLachlan) llega a Twin Peaks, una pequeña población montañosa, para investigar el brutal asesinato de la joven y bella Laura Palmer, la chica más popular del instituto de la localidad. Con la ayuda del sheriff del pueblo, el amable Harry S. Truman (Michael Ontkean), el agente Cooper comienza a interrogar a los habitantes del pueblo y va descubriendo poco a poco que muchos de ellos esconden oscuros y misteriosos secretos.', 'img/posters/TWINPEAKS_POSTER.jpg', '2024-06-07', NULL),
(78, 'Buffy, cazavampiros', 1997, 'La joven Buffy y su madre se mudan desde Los Ángeles a la localidad de Sunnydale. En el subsuelo del pueblo habita el Maestro, el más antiguo y poderoso vampiro que existe. El Maestro está atrapado en el punto místico llamado La Boca del Infierno, que el Maestro trato de abrir cuando, por causa de un terremoto, quedó atrapado, ya hace décadas. En Sunnydale Buffy también conoce a Willow y Xander, que se convierten en sus amigos y que, sin querer, la tendrán que ayudar en su lucha contra el Maestro. Xander se enamora de Buffy desde que la ve por primera vez, sin darse cuenta que Willow, su mejor amiga, lo ama desde niños. Además esta Giles, el bibliotecario de la escuela, que es un Vigilante u Observador, que desde siempre se han dedicado a entrenar y guiar a las Cazadoras, pero sin intervenir directamente en la lucha contra los vampiros. Además Buffy conoce un misterioso aliado, de nombre Angel, del que se enamora. Pero es un amor imposible, pues Angel es un vampiro, aunque por una maldición gitana recobró su alma y ahora lucha contra ellos.', 'img/posters/BUFFY_POSTER.jpg', '2024-06-07', NULL),
(79, 'Death Note', 2006, 'Death Note cuenta la historia sobre un joven llamado Yagami Light. Un aburrido día de clase ve caer un cuaderno negro en el patio de su escuela, titulado Death Note. Según las instrucciones escritas en el mismo cuaderno, aquella persona cuyo nombre sea escrito en dicho cuaderno, morirá. En un principio se cree que es una de esas estúpidas cadenas... pero “Kira”, como será reconocido por las masas, prueba el Death Note... y efectivamente, funciona. Light decide usar el cuaderno desde el anonimato, para limpiar el mundo de todos los criminales que merezcan morir, reinando así la paz y la tranquilidad. Todas las fuerzas de protección internacional están en alerta, pero la Interpol tiene un as en la manga: L, un detective de identidad oculta que ha logrado solucionar casos que se daban por irresolubles. ¿Que pasara con Light y ambicioso proyecto? ¿Podrá L desenmascararle?', 'img/posters/DEATHNOTE_POSTER.jpg', '2024-06-07', NULL),
(80, 'Homeland', 2011, 'El sargento de la Marina Nicholas Brody (Damian Lewis) regresa a casa ocho años después de su desaparición en Irak, donde vivió encarcelado y sometido a tortura. Finalmente, un comando de las fuerzas especiales lo localiza durante una misión. La joven Carrie Mathison (Claire Danes), una impulsiva e intuitiva agente de la CIA, sospecha que Brody se ha pasado al enemigo durante su cautiverio, pues unos meses antes un terrorista condenado a muerte le habló de un soldado norteamericano que había cambiado de bando...', 'img/posters/HOMELAND_POSTER.jpg', '2024-06-07', NULL),
(81, 'Seinfeld', 1989, '\'Seinfeld\' es la telecomedia nº1 de la historia de la TV de los Estados Unidos. Nunca una \"serie sobre nada\" llegó a tanto. El cómico Jerry Seinfeld y sus excéntricos amigos (Elaine, Constanza y Kramer) viven en Nueva York y les pasan innumerables peripecias en esta genial comedia de situación donde la menor excusa sirve para regalarnos un delirante episodio. Batió todos los récords de audiencia que se pusieron por delante, y aún hoy en día sus reposiciones siguen contando con innumerables seguidores, no en vano \"Seinfeld\" es una verdadera leyenda de la televisión americana.', 'img/posters/SEINFELD_POSTER.jpg', '2024-06-07', NULL),
(82, 'El Juego del Calamar', 2021, 'Cientos de jugadores con problemas económicos aceptan una extraña invitación para competir en juegos infantiles. Dentro les esperan un premio tentador y desafíos letales.', 'img/posters/CALAMAR_POSTER.jpg', '2024-06-07', NULL),
(83, 'Westworld', 2016, 'Westworld es un parque de atracciones futurista y controlado por alta tecnología dirigido por el Dr. Robert Ford (Anthony Hopkins). Las instalaciones cuentan con androides cuya apariencia física es humana, y gracias a ellos los visitantes pueden dar rienda suelta a sus instintos y vivir cualquier tipo de aventura o fantasía, por muy oscura o peligrosa que sea, sabiendo que los robots no les harán daño.', 'img/posters/WW_POSTER.jpg', '2024-06-07', NULL);
